import 'package:flutter/material.dart';
import '../services/local_store.dart';
class FieldsPage extends StatefulWidget { const FieldsPage({super.key}); @override State<FieldsPage> createState()=>_FieldsPageState(); }
class _FieldsPageState extends State<FieldsPage>{List<Map<String,dynamic>> fields=[];@override void initState(){super.initState();load();}Future<void>load()async{final x=await LocalStore.getFields();if(mounted)setState(()=>fields=x);}Future<void>addField()async{final name=TextEditingController();final variety=TextEditingController();final location=TextEditingController();await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Add Rice Field'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Field name *')),TextField(controller:variety,decoration:const InputDecoration(labelText:'Rice variety')),TextField(controller:location,decoration:const InputDecoration(labelText:'Location'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()async{if(name.text.trim().isEmpty)return;fields.add({'name':name.text.trim(),'variety':variety.text.trim(),'location':location.text.trim()});await LocalStore.saveFields(fields);if(mounted){setState((){});Navigator.pop(context);}},child:const Text('Save'))]));}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('My Fields',style:TextStyle(fontWeight:FontWeight.w700))),floatingActionButton:FloatingActionButton.extended(onPressed:addField,icon:const Icon(Icons.add),label:const Text('Add field')),body:fields.isEmpty?const Center(child:Text('No fields yet. Add your first rice field.')):ListView.builder(padding:const EdgeInsets.all(16),itemCount:fields.length,itemBuilder:(_,i){final f=fields[i];return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.agriculture)),title:Text(f['name']??'Unnamed field',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text((f['variety']??'Rice').toString())));});}
